    public String greetUser(String username) {
        if (username == null || username.trim().isEmpty()) {
            return "Hello, Guest!";
        }

        // تحاول تنظيف الإدخال عن طريق حظر علامات <script> بشكل صريح.
        // ملاحظة: هذا نهج أساسي جدًا ولا يكفي للحماية الكاملة من هجمات XSS.
