import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Jäsentää ja arvioi käyttäjän antaman matemaattisen lausekkeen.
     * 
     * Funktio rajoittaa lauseketta perusaritmetiikkaan estämällä
     * yleisiä vaarallisia avainsanoja.
     */
    public Object evaluateMathematicalExpression(String expression) throws Exception {
        // Luodaan uusi ScriptEngineManager
        ScriptEngineManager manager = new ScriptEngineManager();
        // Haetaan JavaScript-moottori (Nashorn tai GraalJS)
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Tarkistetaan tunnetut vaaralliset tai ei-aritmeettiset avainsanat
        String[] dangerousKeywords = {
            "System", "Runtime", "ProcessBuilder", "File", "Class", "Object", "Packages",
            "java", "javax", "print", "while", "for", "if", "function", "var", "let", "new",
            "eval", "import", "with", "do", "try", "catch", "throw", "debugger", "await", "async",
            "return", "break", "continue", "switch", "case", "default", "alert", "prompt", "confirm"
        };

        for (String keyword : dangerousKeywords) {
            if (expression.toLowerCase().contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("Expression contains disallowed keyword: " + keyword);
            }
        }

        // Tarkistetaan muita merkkejä, jotka eivät ole numeroita, operaattoreita tai sulkuja
        // Sallitut merkit: 0-9, ., +, -, *, /, %, (, )
        if (!expression.matches("^[0-9+\\-*/%().\\s]+$")) {
            throw new IllegalArgumentException("Expression contains disallowed characters.");
        }

        // Arvioi lauseke
        return engine.eval(expression);
    }
}
